/// Zero-allocation mutable game state read directly by the VSync 120FPS CustomPainter!
class RaceEngineState extends ChangeNotifier {
  static const int totalLaps = 5;
  static const int totalCars = 22;

  final CircuitInfo circuit;
  final TeamLivery livery;
  final TrackGeometry geometry;
  final Random rng = Random();

  bool cockpitCamera = true;
  bool autoGas = false;
  bool raceFinished = false;
  double startLightsTimer = 3.2;

  double speedKmh = 0.0;
  double carX = 0.0;
  double lateralVel = 0.0;
  double steerAngle = 0.0;
  double smoothCamBank = 0.0;
  double smoothPitch = 0.0; // Suspension dive/squat on braking/ERS
  double smoothFovBoost = 0.0; // Dynamic high-speed FOV stretch
  double spinYaw = 0.0;
  double controlRecoveryTimer = 0.0;
  double playerDist = 18.0;
  double horizonPan = 0.0;
  double lapStartTime = 0.0;
  double totalRaceTime = 0.0;
  double bestLapTime = 999.0;
  double fastLapTime = 999.0;
  double hitFlash = 0.0;

  double ersCharge = 100.0;
  bool ersToggledOn = false;

  String radioMessage = '';
  double radioTimer = 0.0;

  bool leftHeld = false;
  bool rightHeld = false;
  bool gasHeld = false;
  bool brakeHeld = false;

  bool rivalCloseLeft = false;
  bool rivalCloseRight = false;

  late List<AiDriver> aiDrivers;
  final List<TrackParticle> particles = [];

  RaceEngineState({
    required this.circuit,
    required this.livery,
  }) : geometry = TrackGeometry.fromWaypoints(circuit.waypoints) {
    _initGrid();
  }

  void _initGrid() {
    const List<Map<String, Object>> gridTemplates = [
      {'c': 'VER', 'b': Color(0xFF13245E), 'hl': Color(0xFF3E64E0), 'w': Color(0xFFE10600), 'h': Color(0xFFFF6D00)},
      {'c': 'NOR', 'b': Color(0xFFFF7A00), 'hl': Color(0xFFFFC178), 'w': Color(0xFF14171C), 'h': Color(0xFFC6FF00)},
      {'c': 'LEC', 'b': Color(0xFFD6131C), 'hl': Color(0xFFFF636C), 'w': Color(0xFFFFD100), 'h': Color(0xFFFFFFFF)},
      {'c': 'PIA', 'b': Color(0xFFFF7A00), 'hl': Color(0xFFFFC178), 'w': Color(0xFF14171C), 'h': Color(0xFF29B6F6)},
      {'c': 'HAM', 'b': Color(0xFFD6131C), 'hl': Color(0xFFFF636C), 'w': Color(0xFFFFFFFF), 'h': Color(0xFFFFEA00)},
      {'c': 'RUS', 'b': Color(0xFF252D36), 'hl': Color(0xFF8196A8), 'w': Color(0xFF00D2BE), 'h': Color(0xFF40C4FF)},
      {'c': 'ANT', 'b': Color(0xFF252D36), 'hl': Color(0xFF8196A8), 'w': Color(0xFF00D2BE), 'h': Color(0xFFE0F7FA)},
      {'c': 'ALO', 'b': Color(0xFF005C52), 'hl': Color(0xFF25BFAD), 'w': Color(0xFFCEDC00), 'h': Color(0xFF00B0FF)},
      {'c': 'STR', 'b': Color(0xFF005C52), 'hl': Color(0xFF25BFAD), 'w': Color(0xFFCEDC00), 'h': Color(0xFF00E676)},
      {'c': 'SAI', 'b': Color(0xFF0055EB), 'hl': Color(0xFF63A4FF), 'w': Color(0xFFFFFFFF), 'h': Color(0xFFFF1744)},
      {'c': 'ALB', 'b': Color(0xFF0055EB), 'hl': Color(0xFF63A4FF), 'w': Color(0xFFFFFFFF), 'h': Color(0xFFFFD54F)},
      {'c': 'GAS', 'b': Color(0xFF0084EB), 'hl': Color(0xFF66C0FF), 'w': Color(0xFFFF69B4), 'h': Color(0xFFE040FB)},
      {'c': 'DOO', 'b': Color(0xFF0084EB), 'hl': Color(0xFF66C0FF), 'w': Color(0xFFFF69B4), 'h': Color(0xFF80D8FF)},
      {'c': 'TSU', 'b': Color(0xFF1735AD), 'hl': Color(0xFF5D80F0), 'w': Color(0xFFFFFFFF), 'h': Color(0xFFFF5252)},
      {'c': 'LAW', 'b': Color(0xFF1735AD), 'hl': Color(0xFF5D80F0), 'w': Color(0xFFFFFFFF), 'h': Color(0xFFFFAB40)},
      {'c': 'HUL', 'b': Color(0xFF1B2129), 'hl': Color(0xFF5B6B7E), 'w': Color(0xFF00E676), 'h': Color(0xFF69F0AE)},
      {'c': 'BOR', 'b': Color(0xFF1B2129), 'hl': Color(0xFF5B6B7E), 'w': Color(0xFF00E676), 'h': Color(0xFFFFD600)},
      {'c': 'OCO', 'b': Color(0xFFD9DEE6), 'hl': Color(0xFFFFFFFF), 'w': Color(0xFFE10600), 'h': Color(0xFFFF1744)},
      {'c': 'BEA', 'b': Color(0xFFD9DEE6), 'hl': Color(0xFFFFFFFF), 'w': Color(0xFFE10600), 'h': Color(0xFF2979FF)},
      {'c': 'RIC', 'b': Color(0xFF1B2C4F), 'hl': Color(0xFF587AB8), 'w': Color(0xFFFFC107), 'h': Color(0xFFFF4081)},
      {'c': 'BOT', 'b': Color(0xFF21252B), 'hl': Color(0xFF626E82), 'w': Color(0xFF00B0FF), 'h': Color(0xFF40C4FF)},
    ];

    aiDrivers = [];
    playerDist = 18.0;
    for (int i = 0; i < gridTemplates.length; i++) {
      final int gridSlot = i < 20 ? (20 - i) : 0;
      final double startDist = gridSlot == 0 ? 4.0 : (playerDist + 16.0 + (gridSlot * 16.0));
      final double lane = (i % 2 == 0) ? -0.45 : 0.45;
      final double pace = 224.0 + ((20 - i) * 2.25);
      aiDrivers.add(
        AiDriver(
          code: gridTemplates[i]['c'] as String,
          bodyColor: gridTemplates[i]['b'] as Color,
          bodyHighlight: gridTemplates[i]['hl'] as Color,
          wingColor: gridTemplates[i]['w'] as Color,
          helmetColor: gridTemplates[i]['h'] as Color,
          laneX: lane,
          trackDist: startDist,
          baseSpeedKmh: pace,
        ),
      );
    }
  }

  int get currentLap => ((playerDist / circuit.lapLengthMeters).floor() + 1).clamp(1, totalLaps).toInt();
  double get lapProgress => (playerDist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
  int get gear => (1 + (speedKmh / 41.0)).clamp(1, 8).toInt();
  int get rpm => (4800 + ((speedKmh % 41.0) / 41.0) * 7600 + (speedKmh > 20 ? 1500 : 0)).clamp(3500, 14500).toInt();
  bool get ersActive => ersToggledOn && ersCharge > 0.5 && !brakeHeld;

  int get currentPosition {
    int ahead = 0;
    for (final ai in aiDrivers) {
      if (ai.trackDist > playerDist) ahead++;
    }
    return (ahead + 1).clamp(1, totalCars).toInt();
  }

  void showRadio(String msg, {double secs = 2.4}) {
    radioMessage = msg;
    radioTimer = secs;
  }

  void spawnParticles(Color color, int count, {bool sparks = false}) {
    for (int i = 0; i < count; i++) {
      particles.add(
        TrackParticle(
          x: 0.25 + rng.nextDouble() * 0.5,
          y: 0.62 + rng.nextDouble() * 0.22,
          vx: (rng.nextDouble() - 0.5) * (sparks ? 1.65 : 0.72),
          vy: (sparks ? -0.58 : -0.22) - rng.nextDouble() * 0.45,
          life: 0.32 + rng.nextDouble() * 0.34,
          color: color,
          radius: sparks ? (2.1 + rng.nextDouble() * 2.4) : (3.0 + rng.nextDouble() * 4.2),
          isSpark: sparks,
        ),
      );
    }
  }

  /// Returns true when the race just finished!
  bool step(double dt) {
    if (raceFinished) return false;

    if (radioTimer > 0) {
      radioTimer = max(0.0, radioTimer - dt);
      if (radioTimer == 0) radioMessage = '';
    }

    if (startLightsTimer > 0) {
      startLightsTimer = max(0.0, startLightsTimer - dt);
      notifyListeners();
      return false;
    }

    totalRaceTime += dt;

    for (int i = particles.length - 1; i >= 0; i--) {
      final TrackParticle p = particles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 1.45 * dt;
      p.life -= dt;
      if (p.life <= 0) particles.removeAt(i);
    }

    _updateAi(dt);

    final int prevLap = currentLap;

    if (brakeHeld && ersToggledOn) {
      ersToggledOn = false;
    }

    final bool ersOn = ersActive;
    if (ersOn) {
      ersCharge = max(0.0, ersCharge - 21.0 * dt);
      if (ersCharge <= 0.5) {
        ersToggledOn = false;
        showRadio('BATERÍA ERS AGOTADA', secs: 1.8);
      }
    } else {
      final double rechargeRate = brakeHeld ? 26.0 : 6.8;
      ersCharge = min(100.0, ersCharge + rechargeRate * dt);
    }

    final bool effectivelyAccelerating = (gasHeld || autoGas || ersOn) && !brakeHeld;
    final double maxSpeed = ersOn ? 360.0 : 322.0;

    double targetPitch = 0.0;
    if (effectivelyAccelerating) {
      final double accel = ersOn ? 180.0 : 128.0;
      speedKmh = min(maxSpeed, speedKmh + accel * dt);
      targetPitch = ersOn ? -1.0 : -0.35;
    } else if (brakeHeld) {
      speedKmh = max(0.0, speedKmh - 288.0 * dt);
      targetPitch = speedKmh > 30 ? 1.0 : 0.0;
    } else {
      speedKmh = max(0.0, speedKmh - 36.0 * dt);
    }

    // Smooth camera pitch (nose dive/lift) & dynamic speed FOV
    smoothPitch += (targetPitch - smoothPitch) * (1.0 - exp(-9.0 * dt));
    final double targetFov = ((speedKmh - 140.0) / 220.0).clamp(0.0, 1.0).toDouble() + (ersOn ? 0.25 : 0.0);
    smoothFovBoost += (targetFov - smoothFovBoost) * (1.0 - exp(-5.0 * dt));

    // Silky-smooth progressive steering interpolation
    double targetSteer = 0.0;
    if (leftHeld) targetSteer -= 1.0;
    if (rightHeld) targetSteer += 1.0;
    steerAngle += (targetSteer - steerAngle) * (1.0 - exp(-13.5 * dt));

    final double realCurve = geometry.curvatureAtProgress(lapProgress);
    horizonPan = (horizonPan - realCurve * (speedKmh / 300.0) * dt * 135.0) % 2400.0;

    // Subtle look-to-apex camera bank
    final double targetBank = (steerAngle * 0.025) - (realCurve * (speedKmh / 350.0) * 0.012);
    smoothCamBank += (targetBank - smoothCamBank) * (1.0 - exp(-8.0 * dt));

    final double centrifugal = realCurve * pow(speedKmh / 275.0, 1.45).toDouble() * 0.84;

    if (controlRecoveryTimer > 0) {
      controlRecoveryTimer = max(0.0, controlRecoveryTimer - dt);
    }

    final bool offTrack = carX.abs() > 1.02;
    final double steerAuthority = (offTrack ? 0.56 : 1.0) * (controlRecoveryTimer > 0 ? 0.42 : 1.0);
    final double steerForce = steerAngle * (1.62 + speedKmh / 255.0) * steerAuthority;

    lateralVel += (steerForce - centrifugal) * dt * 4.3;
    final double lateralDamping = offTrack ? 2.3 : (controlRecoveryTimer > 0 ? 1.8 : 5.0);
    lateralVel *= exp(-lateralDamping * dt);
    carX += lateralVel * dt;
    spinYaw *= exp(-4.8 * dt);

    if (offTrack) {
      speedKmh = max(48.0, speedKmh - (138.0 + speedKmh * 0.35) * dt);
      if (speedKmh > 65.0 && rng.nextDouble() < 0.42) {
        spawnParticles(const Color(0xFFC2AA82), 2);
      }
      if (carX.abs() >= 1.52) {
        final double wallSign = carX >= 0 ? 1.0 : -1.0;
        carX = wallSign * 1.50;
        lateralVel = -wallSign * 1.75;
        spinYaw = -wallSign * 0.30;
        speedKmh = max(35.0, speedKmh * 0.48);
        hitFlash = 1.0;
        ersToggledOn = false;
        spawnParticles(const Color(0xFFFFB300), 14, sparks: true);
        showRadio('¡IMPACTO CONTRA EL MURO!', secs: 2.0);
      }
    }

    final double distStep = (speedKmh / 3.6) * dt;
    playerDist += distStep;

    if (hitFlash > 0) hitFlash = max(0.0, hitFlash - dt * 2.8);

    final int newLap = (playerDist / circuit.lapLengthMeters).floor() + 1;
    if (newLap > prevLap) {
      final double lapDuration = totalRaceTime - lapStartTime;
      lapStartTime = totalRaceTime;
      if (lapDuration < bestLapTime) bestLapTime = lapDuration;
      if (lapDuration < fastLapTime) fastLapTime = lapDuration;

      if (newLap > totalLaps) {
        raceFinished = true;
        notifyListeners();
        return true;
      }
    }

    notifyListeners();
    return false;
  }

  void _updateAi(double dt) {
    rivalCloseLeft = false;
    rivalCloseRight = false;

    for (final ai in aiDrivers) {
      final double aiProgress = (ai.trackDist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
      final double aiCurve = geometry.curvatureAtProgress(aiProgress).abs();
      final double cornerSlowdown = (1.0 - (aiCurve * 0.14)).clamp(0.58, 1.0).toDouble();

      double pace = ai.baseSpeedKmh * cornerSlowdown;
      final double deltaToPlayer = playerDist - ai.trackDist;
      if (deltaToPlayer > 240) pace += 16.0;
      if (deltaToPlayer < -340) pace -= 12.0;

      ai.trackDist += (pace / 3.6) * dt;

      if (rng.nextDouble() < 0.015) {
        ai.targetLaneX = [-0.62, -0.20, 0.20, 0.62][rng.nextInt(4)];
      }
      ai.lateralVel *= exp(-5.0 * dt);
      ai.laneX += ((ai.targetLaneX - ai.laneX) * 1.6 + ai.lateralVel) * dt;
      ai.laneX = ai.laneX.clamp(-1.25, 1.25).toDouble();

      // Mirror proximity radar
      final double behindDist = playerDist - ai.trackDist;
      if (behindDist > 2.0 && behindDist < 30.0) {
        if (ai.laneX <= carX) {
          rivalCloseLeft = true;
        } else {
          rivalCloseRight = true;
        }
      }

      // Realistic Wheel-to-Wheel Collision -> Sends car flying off-track!
      final double dz = ai.trackDist - playerDist;
      if (dz > -4.6 && dz < 5.0 && (ai.laneX - carX).abs() < 0.35) {
        final double pushDir = (carX >= ai.laneX) ? 1.0 : -1.0;
        final double relImpact = (speedKmh / 200.0).clamp(0.65, 1.85).toDouble();

        lateralVel = pushDir * (2.95 * relImpact);
        spinYaw = pushDir * 0.38;
        controlRecoveryTimer = 0.70;
        speedKmh = max(50.0, speedKmh * 0.58);
        hitFlash = 1.0;
        ersToggledOn = false;

        ai.lateralVel = -pushDir * 1.95;
        carX += pushDir * 0.14;

        spawnParticles(const Color(0xFFFFD54F), 16, sparks: true);
        showRadio('¡CONTACTO CON ${ai.code}! FUERA DE PISTA', secs: 2.2);
      }
    }
  }
}

class CockpitRaceScreen extends StatefulWidget {
  final CircuitInfo circuit;
  final TeamLivery livery;

  const CockpitRaceScreen({
    super.key,
    required this.circuit,
    required this.livery,
  });

  @override
  State<CockpitRaceScreen> createState() => _CockpitRaceScreenState();
}

class _CockpitRaceScreenState extends State<CockpitRaceScreen> with SingleTickerProviderStateMixin {
  late final RaceEngineState engine;
  late final Ticker _ticker;
  final ValueNotifier<int> _hudTick = ValueNotifier<int>(0);
  Duration _lastElapsed = Duration.zero;
  double _hudAccumulator = 0.0;

  @override
  void initState() {
    super.initState();
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
    engine = RaceEngineState(circuit: widget.circuit, livery: widget.livery);
    _ticker = createTicker(_onTick)..start();
  }

  void _onTick(Duration elapsed) {
    final double rawDt = (elapsed - _lastElapsed).inMicroseconds / 1000000.0;
    _lastElapsed = elapsed;
    if (rawDt <= 0.0) return;
    final double dt = rawDt.clamp(0.001, 0.045).toDouble();

    final bool finishedNow = engine.step(dt);
    if (finishedNow) {
      _ticker.stop();
      _hudTick.value++;
      _showFinishDialog();
      return;
    }

    // Update lightweight HUD widgets at ~16Hz while 3D Canvas runs at full 60/90/120Hz VSync!
    _hudAccumulator += dt;
    if (_hudAccumulator >= 0.06) {
      _hudAccumulator = 0.0;
      _hudTick.value++;
    }
  }

  @override
  void dispose() {
    _ticker.dispose();
    engine.dispose();
    _hudTick.dispose();
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.portraitUp,
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
    super.dispose();
  }

  String _formatTime(double seconds) {
    if (seconds >= 900) return '--:--.---';
    final int mins = seconds ~/ 60;
    final int secs = seconds.toInt() % 60;
    final int ms = ((seconds - seconds.floor()) * 1000).toInt();
    return '${mins.toString().padLeft(2, '0')}:${secs.toString().padLeft(2, '0')}.${ms.toString().padLeft(3, '0')}';
  }

  int _pointsForPos(int pos) {
    const List<int> table = [25, 18, 15, 12, 10, 8, 6, 4, 2, 1];
    return pos <= 10 ? table[pos - 1] : 0;
  }

  void _toggleErs() {
    if (engine.startLightsTimer > 0) return;
    if (!engine.ersToggledOn && engine.ersCharge < 5.0) {
      engine.showRadio('BATERÍA ERS BAJA — FRENA PARA RECARGAR', secs: 2.0);
      _hudTick.value++;
      return;
    }
    engine.ersToggledOn = !engine.ersToggledOn;
    _hudTick.value++;
  }

  void _showFinishDialog() {
    final int pos = engine.currentPosition;
    final int pts = _pointsForPos(pos);
    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) {
        return AlertDialog(
          backgroundColor: const Color(0xFF0E1420),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
            side: BorderSide(color: pos <= 3 ? const Color(0xFFFFD54F) : const Color(0xFFE10600), width: 2),
          ),
          title: Text(
            'BANDERA A CUADROS — ${widget.circuit.gpName}',
            style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w900),
            textAlign: TextAlign.center,
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                'POSICIÓN P$pos / ${RaceEngineState.totalCars}',
                style: TextStyle(
                  fontSize: 26,
                  fontWeight: FontWeight.w900,
                  color: pos == 1 ? const Color(0xFFFFD54F) : Colors.white,
                ),
              ),
              const SizedBox(height: 8),
              Text('Puntos obtenidos: +$pts PTS', style: const TextStyle(color: Color(0xFF00E676), fontWeight: FontWeight.bold)),
              const SizedBox(height: 4),
              Text('Mejor vuelta: ${_formatTime(engine.bestLapTime)}', style: const TextStyle(color: Colors.white70)),
              Text('Tiempo total: ${_formatTime(engine.totalRaceTime)}', style: const TextStyle(color: Colors.white70)),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(ctx);
                Navigator.pop(context, RaceFinishData(position: pos, points: pts, nextRound: false));
              },
              child: const Text('CALENDARIO'),
            ),
            if (widget.circuit.round < 24)
              ElevatedButton(
                style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFFE10600), foregroundColor: Colors.white),
                onPressed: () {
                  Navigator.pop(ctx);
                  Navigator.pop(context, RaceFinishData(position: pos, points: pts, nextRound: true));
                },
                child: const Text('SIGUIENTE GP >'),
              ),
          ],
        );
      },
    );
  }

  List<Map<String, Object>> _getMiniLeaderboard() {
    final List<Map<String, Object>> entries = [
      {'code': 'YOU', 'dist': engine.playerDist, 'color': widget.livery.primary, 'isPlayer': true},
      ...engine.aiDrivers.map((a) => {'code': a.code, 'dist': a.trackDist, 'color': a.bodyColor, 'isPlayer': false}),
    ];
    entries.sort((a, b) => (b['dist'] as double).compareTo(a['dist'] as double));

    final int pIdx = entries.indexWhere((e) => e['isPlayer'] == true);
    final int start = max(0, min(entries.length - 3, pIdx - 1));
    final List<Map<String, Object>> slice = [];
    for (int i = start; i < min(entries.length, start + 3); i++) {
      final double gapMeters = (entries[start]['dist'] as double) - (entries[i]['dist'] as double);
      final double gapSec = gapMeters / 65.0;
      slice.add({
        'pos': i + 1,
        'code': entries[i]['code'] as String,
        'color': entries[i]['color'] as Color,
        'isPlayer': entries[i]['isPlayer'] as bool,
        'gap': i == start ? 'GAP' : '+${gapSec.toStringAsFixed(3)}',
      });
    }
    return slice;
  }

