class RealCircuitMinimapPainter extends CustomPainter {
  final TrackGeometry geometry;
  final double playerProgress;
  final List<double> aiProgresses;
  final Color kerbColor;

  RealCircuitMinimapPainter({
    required this.geometry,
    required this.playerProgress,
    required this.aiProgresses,
    required this.kerbColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double cx = size.width * 0.5;
    final double cy = size.height * 0.5;
    final double r = min(size.width, size.height) * 0.46;

    final Path path = Path();
    for (int i = 0; i < geometry.smoothPoints.length; i++) {
      final Offset p = geometry.smoothPoints[i];
      final double x = cx + p.dx * r;
      final double y = cy + p.dy * r;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }
    path.close();

    canvas.drawPath(
      path,
      Paint()
        ..isAntiAlias = true
        ..color = Colors.white70
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.6
        ..strokeJoin = StrokeJoin.round,
    );

    final Offset sf = geometry.pointAtProgress(0.0);
    canvas.drawCircle(Offset(cx + sf.dx * r, cy + sf.dy * r), 3.0, Paint()..isAntiAlias = true..color = kerbColor);

    final Paint aiPaint = Paint()..isAntiAlias = true..color = const Color(0xAAFF5252);
    for (final prog in aiProgresses) {
      final Offset ap = geometry.pointAtProgress(prog);
      canvas.drawCircle(Offset(cx + ap.dx * r, cy + ap.dy * r), 1.8, aiPaint);
    }

    final Offset pp = geometry.pointAtProgress(playerProgress);
    canvas.drawCircle(Offset(cx + pp.dx * r, cy + pp.dy * r), 3.9, Paint()..isAntiAlias = true..color = const Color(0xFF00E676));
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

class F1Pro120FpsPainter extends CustomPainter {
  final RaceEngineState engine;

  // Reusable pre-allocated arrays & paints for zero-GC 120FPS smoothness
  static const int segCount = 120;
  final List<double> _segZ = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segShift = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segElev = List<double>.filled(segCount + 2, 0.0);
  final Paint _fillPaint = Paint()..isAntiAlias = true;

  F1Pro120FpsPainter({required this.engine}) : super(repaint: engine);

  double _curveAtWorldDist(double dist) {
    final double prog = (dist % engine.circuit.lapLengthMeters) / engine.circuit.lapLengthMeters;
    return engine.geometry.curvatureAtProgress(prog);
  }

  double _hillAtWorldDist(double dist) {
    final double prog = (dist % engine.circuit.lapLengthMeters) / engine.circuit.lapLengthMeters;
    return sin(prog * pi * 4.0 + engine.circuit.round) * engine.circuit.hillAmp;
  }

  Offset _project(double x, double y, double z, double w, double horizonY, double fovMult) {
    final double fov = w * fovMult;
    final double scale = fov / max(z, 0.18);
    return Offset(w * 0.5 + x * scale, horizonY - y * scale);
  }

  @override
  void paint(Canvas canvas, Size size) {
    final CircuitInfo circuit = engine.circuit;
    final double w = size.width;
    final double h = size.height;
    final bool cockpit = engine.cockpitCamera;

    // Subtle suspension pitch shifts horizon slightly under heavy braking / ERS acceleration
    final double pitchOffset = engine.smoothPitch * (cockpit ? 7.5 : 4.5);
    final double horizonY = (cockpit ? h * 0.452 : h * 0.422) + pitchOffset;
    final double fovMult = 0.60 - (engine.smoothFovBoost * 0.055);

    canvas.save();
    final double totalRoll = engine.smoothCamBank + engine.spinYaw * 0.22;
    if (totalRoll.abs() > 0.001) {
      canvas.translate(w * 0.5, h * 0.5);
      canvas.rotate(totalRoll);
      canvas.translate(-w * 0.5, -h * 0.5);
    }

    // 1. Photorealistic Multi-Layer Sky, Volumetric Sun, Clouds, Parallax Mountains & Crowd Grandstands
    _drawProEnvironment(canvas, w, h, horizonY, circuit);

    // 2. Ground with Perspective Depth Gradient + Procedural Turf/Gravel Micro-Grain
    final Rect groundRect = Rect.fromLTWH(0, horizonY, w, h - horizonY + 40);
    canvas.drawRect(
      groundRect,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            Color.lerp(circuit.groundColor, circuit.skyBottom, 0.42)!,
            circuit.groundColor,
            Color.lerp(circuit.groundColor, Colors.black, 0.36)!,
          ],
        ).createShader(groundRect),
    );
    if (ProTextures.turfGrainShader != null) {
      canvas.save();
      final double scrollG = (engine.playerDist * 10.0) % 128.0;
      canvas.translate(0, scrollG);
      canvas.drawRect(
        Rect.fromLTWH(0, horizonY - 128, w, h - horizonY + 256),
        Paint()..shader = ProTextures.turfGrainShader..filterQuality = FilterQuality.medium,
      );
      canvas.restore();
    }

    // 3. Ultra-Smooth 120-Slice 3D Track with Quadratic Near-Field Precision, Elevation, 3D Kerbs, Braking Boards & Catch-Fencing
    const double roadHalfW = 3.20;
    const double kerbOuterW = 3.64;
    const double astroOuterW = 4.05;
    const double runoffHalfW = 5.35;
    const double baseSegLen = 0.72;
    final double zOffset = engine.playerDist % baseSegLen;
    final double baseCamHeight = cockpit ? -1.16 : -1.86;
    final double playerHill = _hillAtWorldDist(engine.playerDist);

    double dxAcc = 0.0;
    double xAcc = 0.0;
    for (int i = 1; i <= segCount + 1; i++) {
      // Slight progressive stretching in far distance for extra-long draw distance & razor-sharp near slices
      final double zVal = (i * baseSegLen) + (i * i * 0.0022) - zOffset;
      _segZ[i] = zVal;
      final double wd = engine.playerDist + zVal * 2.0;
      final double k = _curveAtWorldDist(wd);
      dxAcc += k * 0.0068;
      xAcc += dxAcc;
      _segShift[i] = xAcc;
      _segElev[i] = (_hillAtWorldDist(wd) - playerHill) * (i / segCount);
    }

    final double camShift = engine.carX * 2.45 + engine.spinYaw * 1.4;
    final Path asphaltClipPath = Path();

    for (int i = segCount; i >= 1; i--) {
      final double z1 = _segZ[i];
      final double z2 = _segZ[i + 1];
      if (z1 <= 0.28) continue;

      final double worldDist1 = engine.playerDist + z1 * 2.0;
      final int segIndex = (worldDist1 / 1.8).floor();

      final double s1 = _segShift[i] - camShift;
      final double s2 = _segShift[i + 1] - camShift;
      final double y1 = baseCamHeight + _segElev[i];
      final double y2 = baseCamHeight + _segElev[i + 1];

      final double depthT = (i / segCount).clamp(0.0, 1.0).toDouble();
      final double fogMix = pow(depthT, 2.2).toDouble() * 0.80;

      // Painted Tarmac Runoff Area with subtle diagonal striping
      final Offset r1L = _project(-runoffHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset r1R = _project(runoffHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset r2L = _project(-runoffHalfW + s2, y2, z2, w, horizonY, fovMult);
      final Offset r2R = _project(runoffHalfW + s2, y2, z2, w, horizonY, fovMult);

      final Color runoffCol = Color.lerp(
        segIndex % 2 == 0 ? circuit.runoffColor : Color.lerp(circuit.runoffColor, Colors.black, 0.08)!,
        circuit.skyBottom,
        fogMix,
      )!;
      _drawQuad(canvas, r1L, r1R, r2R, r2L, runoffCol);

      // 3D Raised Armco / Tecpro Side Barriers + Sponsor Panel Bands
      const double wallH = 0.76;
      final Offset w1LT = _project(-runoffHalfW + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset w2LT = _project(-runoffHalfW + s2, y2 + wallH, z2, w, horizonY, fovMult);
      final Offset w1RT = _project(runoffHalfW + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset w2RT = _project(runoffHalfW + s2, y2 + wallH, z2, w, horizonY, fovMult);

      final Color wallBase = (segIndex % 10 < 5)
          ? const Color(0xFF171E29)
          : (segIndex % 20 < 10 ? circuit.kerbA : const Color(0xFFEAEFF5));
      final Color wallCol = Color.lerp(wallBase, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, r1L, w1LT, w2LT, r2L, wallCol);
      _drawQuad(canvas, r1R, r2R, w2RT, w1RT, wallCol);

      // Metallic FIA Catch-Fencing Posts + Top Cable
      if (i % 6 == 0 && i < segCount - 16) {
        final Offset fLT = _project(-runoffHalfW + s1, y1 + 1.92, z1, w, horizonY, fovMult);
        final Offset fRT = _project(runoffHalfW + s1, y1 + 1.92, z1, w, horizonY, fovMult);
        final Paint fencePaint = Paint()
          ..color = Color.lerp(const Color(0x6AB0BEC5), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, 4.2 / z1);
        canvas.drawLine(w1LT, fLT, fencePaint);
        canvas.drawLine(w1RT, fRT, fencePaint);
      }

      // Outer Green Astro-Turf Verge behind Kerbs (like real modern FIA circuits!)
      final Offset a1LO = _project(-astroOuterW + s1, y1 + 0.02, z1, w, horizonY, fovMult);
      final Offset a2LO = _project(-astroOuterW + s2, y2 + 0.02, z2, w, horizonY, fovMult);
      final Offset a1RO = _project(astroOuterW + s1, y1 + 0.02, z1, w, horizonY, fovMult);
      final Offset a2RO = _project(astroOuterW + s2, y2 + 0.02, z2, w, horizonY, fovMult);
      final Offset k1LO = _project(-kerbOuterW + s1, y1 + 0.055, z1, w, horizonY, fovMult);
      final Offset k2LO = _project(-kerbOuterW + s2, y2 + 0.055, z2, w, horizonY, fovMult);
      final Offset k1RO = _project(kerbOuterW + s1, y1 + 0.055, z1, w, horizonY, fovMult);
      final Offset k2RO = _project(kerbOuterW + s2, y2 + 0.055, z2, w, horizonY, fovMult);

      final Color astroCol = Color.lerp(const Color(0xFF1A5E32), circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, a1LO, k1LO, k2LO, a2LO, astroCol);
      _drawQuad(canvas, k1RO, a1RO, a2RO, k2RO, astroCol);

      // 3D Raised Trapezoidal Kerbs
      final Offset p1L = _project(-roadHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset p1R = _project(roadHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset p2L = _project(-roadHalfW + s2, y2, z2, w, horizonY, fovMult);
      final Offset p2R = _project(roadHalfW + s2, y2, z2, w, horizonY, fovMult);

      final Color kerbCol = Color.lerp(segIndex % 2 == 0 ? circuit.kerbA : circuit.kerbB, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, k1LO, p1L, p2L, k2LO, kerbCol);
      _drawQuad(canvas, p1R, k1RO, k2RO, p2R, kerbCol);

      // Asphalt surface
      final bool isStartLine = (worldDist1 % circuit.lapLengthMeters) < 5.5;
      final Color rawAsphalt = isStartLine
          ? const Color(0xFFF0F3F7)
          : (segIndex % 2 == 0 ? const Color(0xFF333841) : const Color(0xFF2D323B));
      final Color asphaltCol = Color.lerp(rawAsphalt, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, p1L, p1R, p2R, p2L, asphaltCol);

      // Collect near-field road quad for high-res GPU asphalt aggregate grain
      if (i < 54) {
        asphaltClipPath
          ..moveTo(p1L.dx, p1L.dy)
          ..lineTo(p1R.dx, p1R.dy)
          ..lineTo(p2R.dx, p2R.dy)
          ..lineTo(p2L.dx, p2L.dy)
          ..close();
      }

      // Rubbered-in racing groove + sunlit/floodlight asphalt reflection sheen
      if (!isStartLine) {
        final Offset g1L = _project(-1.55 + s1, y1, z1, w, horizonY, fovMult);
        final Offset g1R = _project(1.55 + s1, y1, z1, w, horizonY, fovMult);
        final Offset g2L = _project(-1.55 + s2, y2, z2, w, horizonY, fovMult);
        final Offset g2R = _project(1.55 + s2, y2, z2, w, horizonY, fovMult);
        _drawQuad(canvas, g1L, g1R, g2R, g2L, Color.fromARGB((28 * (1.0 - fogMix)).toInt(), 0, 0, 0));

        final Offset sh1L = _project(-0.46 + s1, y1, z1, w, horizonY, fovMult);
        final Offset sh1R = _project(0.46 + s1, y1, z1, w, horizonY, fovMult);
        final Offset sh2L = _project(-0.46 + s2, y2, z2, w, horizonY, fovMult);
        final Offset sh2R = _project(0.46 + s2, y2, z2, w, horizonY, fovMult);
        _drawQuad(
          canvas,
          sh1L,
          sh1R,
          sh2R,
          sh2L,
          Color.fromARGB(((circuit.nightMode ? 32 : 22) * (1.0 - fogMix)).toInt(), 255, 255, 255),
        );
      }

      // Crisp White FIA Track-Limit Lines
      final Paint linePaint = Paint()
        ..isAntiAlias = true
        ..color = Color.lerp(const Color(0xF2F6F9FC), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 4.4 / z1);
      canvas.drawLine(p1L, p2L, linePaint);
      canvas.drawLine(p1R, p2R, linePaint);

      // Realistic 150 / 100 / 50m Braking Marker Boards before sharp corners!
      if (i % 14 == 0 && i > 4 && i < 66) {
        final double aheadK = _curveAtWorldDist(worldDist1 + 95.0);
        if (aheadK.abs() > 1.35) {
          final bool onLeft = aheadK > 0;
          final double bx = (onLeft ? -runoffHalfW + 0.35 : runoffHalfW - 0.35) + s1;
          final String distTxt = i > 42 ? '150' : (i > 22 ? '100' : '50');
          _drawBrakingBoard(canvas, bx, y1, z1, w, horizonY, fovMult, distTxt, fogMix);
        }
      }

      // Trackside environment props
      if (i % 11 == 0 && i < segCount - 10) {
        _drawTracksideProp(canvas, -runoffHalfW - 1.8 + s1, y1, z1, w, horizonY, fovMult, fogMix, circuit);
        _drawTracksideProp(canvas, runoffHalfW + 1.8 + s1, y1, z1, w, horizonY, fovMult, fogMix, circuit);
      }

      // Overhead Start/Finish LED Bridge
      if (isStartLine && i > 3 && i < 72) {
        _drawStartGantry(canvas, s1, y1, z1, roadHalfW, w, horizonY, fovMult, fogMix, circuit);
      }
    }

    // Apply High-Res GPU Asphalt Micro-Aggregate Texture across the road!
    if (ProTextures.asphaltGrainShader != null) {
      canvas.save();
      canvas.clipPath(asphaltClipPath);
      final double scrollY = (engine.playerDist * 22.0) % 192.0;
      canvas.translate(0, scrollY);
      canvas.drawRect(
        Rect.fromLTWH(0, horizonY - 192, w, h - horizonY + 384),
        Paint()..shader = ProTextures.asphaltGrainShader..filterQuality = FilterQuality.high,
      );
      canvas.restore();
    }

    // Smooth atmospheric horizon haze strip
    canvas.drawRect(
      Rect.fromLTWH(0, horizonY - 14, w, 30),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            circuit.skyBottom.withAlpha(0),
            circuit.skyBottom.withAlpha(165),
            circuit.skyBottom.withAlpha(0),
          ],
        ).createShader(Rect.fromLTWH(0, horizonY - 14, w, 30)),
    );

    // 4. Sculpted 3D Perspective Rival F1 Cars (sorted far -> near)
    final List<AiDriver> visibleRivals = engine.aiDrivers.where((ai) {
      final double dz = (ai.trackDist - engine.playerDist) / 2.0;
      return dz > 1.2 && dz < 88.0;
    }).toList()
      ..sort((a, b) => b.trackDist.compareTo(a.trackDist));

    for (final ai in visibleRivals) {
      final double z = (ai.trackDist - engine.playerDist) / 2.0;
      // Find matching slice index smoothly
      int idx = 1;
      for (int s = 1; s < segCount; s++) {
        if (_segZ[s] >= z) {
          idx = s;
          break;
        }
      }
      final double rx = (ai.laneX * 2.45) + _segShift[idx] - camShift;
      final double ry = baseCamHeight + _segElev[idx];
      final Offset pos = _project(rx, ry, z, w, horizonY, fovMult);
      final double sc = (w * fovMult) / max(z, 0.5);
      // Perspective yaw angle: cars on left/right show true 3D sidepod depth!
      final double viewParallax = ((pos.dx - w * 0.5) / (w * 0.5)).clamp(-1.0, 1.0).toDouble();
      _drawRivalF1CarPro(canvas, pos, sc, viewParallax, ai);
    }

    // 5. Sparks & Gravel Particles
    for (final p in engine.particles) {
      final Offset pt = Offset(p.x * w, p.y * h);
      if (p.isSpark) {
        canvas.drawLine(
          pt,
          Offset(pt.dx - p.vx * 12, pt.dy - p.vy * 12),
          Paint()
            ..isAntiAlias = true
            ..color = p.color
            ..strokeWidth = p.radius
            ..strokeCap = StrokeCap.round,
        );
      } else {
        canvas.drawCircle(pt, p.radius, Paint()..isAntiAlias = true..color = p.color);
      }
    }

    canvas.restore();

    // 6. Photorealistic Sculpted Cockpit OR Chase Car
    if (cockpit) {
      _drawCockpitPro(canvas, w, h, circuit);
    } else {
      _drawChaseCarPro(canvas, w, h);
    }

    // 7. High-Speed Motion Blur Streaks & ERS Cyan Surge
    final bool ersOn = engine.ersActive;
    if (engine.speedKmh > 250 || ersOn) {
      final double alphaFrac = ((engine.speedKmh - 245) / 110.0).clamp(0.12, 0.72).toDouble();
      final Paint streakPaint = Paint()
        ..isAntiAlias = true
        ..color = ersOn
            ? Color.fromARGB((alphaFrac * 115).toInt(), 0, 229, 255)
            : Color.fromARGB((alphaFrac * 92).toInt(), 255, 255, 255)
        ..strokeWidth = 1.7;
      for (int k = 0; k < 12; k++) {
        final double lx = (k.isEven ? 0.03 + (k * 0.009) : 0.97 - (k * 0.009)) * w;
        final double ly = ((engine.playerDist * 28 + k * 60) % h);
        canvas.drawLine(Offset(lx, ly), Offset(lx, ly + 44), streakPaint);
      }
    }

    // 8. Cinematic Lens Vignette
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, h),
      Paint()
        ..shader = const RadialGradient(
          radius: 1.06,
          stops: [0.66, 1.0],
          colors: [Color(0x00000000), Color(0x52000000)],
        ).createShader(Rect.fromLTWH(0, 0, w, h)),
    );

    // 9. Collision Impact Red Vignette
    if (engine.hitFlash > 0) {
      canvas.drawRect(
        Rect.fromLTWH(0, 0, w, h),
        Paint()
          ..shader = RadialGradient(
            radius: 0.95,
            colors: [
              const Color(0x00FF0000),
              Color.fromARGB((engine.hitFlash * 160).toInt(), 255, 18, 18),
            ],
          ).createShader(Rect.fromLTWH(0, 0, w, h)),
      );
    }
  }

  void _drawQuad(Canvas canvas, Offset a, Offset b, Offset c, Offset d, Color color) {
    final Path p = Path()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(c.dx, c.dy)
      ..lineTo(d.dx, d.dy)
      ..close();
    _fillPaint.color = color;
    canvas.drawPath(p, _fillPaint);
  }

  void _drawBrakingBoard(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    String text,
    double fogMix,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    final Offset top = _project(x, y1 + 1.35, z, w, horizonY, fovMult);
    final double bh = max(6.0, base.dy - top.dy);
    final double bw = bh * 1.15;
    if (bw < 8.0) return;

    final Rect board = Rect.fromLTWH(top.dx - bw * 0.5, top.dy, bw, bh * 0.68);
    canvas.drawRect(board, Paint()..color = Color.lerp(const Color(0xFFF5F7FA), engine.circuit.skyBottom, fogMix)!);
    canvas.drawRect(
      board,
      Paint()
        ..color = Color.lerp(const Color(0xFFE10600), engine.circuit.skyBottom, fogMix)!
        ..style = PaintingStyle.stroke
        ..strokeWidth = max(1.0, bw * 0.08),
    );
    if (bw > 16.0) {
      _drawCenteredText(canvas, text, board.center, (bh * 0.34).clamp(7.0, 14.0).toDouble(), const Color(0xFF11141A), FontWeight.w900);
    }
  }

  void _drawProEnvironment(Canvas canvas, double w, double h, double horizonY, CircuitInfo circuit) {
    final Color skyMid = Color.lerp(circuit.skyTop, circuit.skyBottom, 0.56)!;
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, horizonY),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.52, 1.0],
          colors: [circuit.skyTop, skyMid, circuit.skyBottom],
        ).createShader(Rect.fromLTWH(0, 0, w, horizonY)),
    );

    // Hardware-accelerated RadialGradient Sun / Moon Bloom (zero Blur overhead!)
    final double sunX = ((w * 0.72 + engine.horizonPan * 0.14) % (w * 1.4)) - w * 0.2;
    final Offset sunCenter = Offset(sunX, horizonY * 0.38);
    final double haloR = circuit.nightMode ? 52.0 : 145.0;
    canvas.drawCircle(
      sunCenter,
      haloR,
      Paint()
        ..shader = RadialGradient(
          colors: circuit.nightMode
              ? const [Color(0xBBEBF5FF), Color(0x38A3CFFF), Color(0x00000000)]
              : const [Color(0xEEFFFCE8), Color(0x66FFD285), Color(0x00FFD285)],
        ).createShader(Rect.fromCircle(center: sunCenter, radius: haloR)),
    );

    if (circuit.nightMode) {
      final Paint starPaint = Paint()..color = const Color(0xAAFFFFFF);
      for (int s = 0; s < 36; s++) {
        final double sx = ((s * 97.0 + engine.horizonPan * 0.08) % w + w) % w;
        final double sy = (s * 27.0) % (horizonY * 0.65);
        canvas.drawCircle(Offset(sx, sy), (s % 3 == 0) ? 1.4 : 0.9, starPaint);
      }
    } else {
      for (int c = 0; c < 6; c++) {
        final double cx = ((c * 240.0 + engine.horizonPan * 0.18) % (w + 280)) - 140;
        final double cy = horizonY * (0.20 + (c % 3) * 0.15);
        final Rect cr = Rect.fromCenter(center: Offset(cx, cy), width: 210, height: 34);
        canvas.drawOval(
          cr,
          Paint()
            ..shader = const RadialGradient(
              colors: [Color(0x45FFFFFF), Color(0x00FFFFFF)],
            ).createShader(cr),
        );
      }
    }

    // Two-Layer Parallax Distant Mountains / City Skyline
    final Path backRange = Path()..moveTo(0, horizonY);
    for (double x = 0; x <= w + 40; x += 32) {
      final double wx = x - engine.horizonPan * 0.24;
      final double pk = 24.0 + sin(wx * 0.009) * 20.0 + cos(wx * 0.023) * 11.0;
      backRange.lineTo(x, horizonY - pk);
    }
    backRange.lineTo(w, horizonY);
    backRange.close();
    canvas.drawPath(
      backRange,
      Paint()..color = Color.lerp(circuit.nightMode ? const Color(0xFF0A1020) : const Color(0xFF31445C), circuit.skyBottom, 0.45)!,
    );

    final Path frontRange = Path()..moveTo(0, horizonY);
    for (double x = 0; x <= w + 40; x += 34) {
      final double wx = x - engine.horizonPan * 0.36;
      final double pk = circuit.propStyle == PropStyle.skyline
          ? (22.0 + ((wx ~/ 40).abs() % 6) * 14.0)
          : (15.0 + sin(wx * 0.015 + 1.2) * 15.0 + cos(wx * 0.032) * 8.0);
      frontRange.lineTo(x, horizonY - pk);
    }
    frontRange.lineTo(w, horizonY);
    frontRange.close();
    canvas.drawPath(
      frontRange,
      Paint()..color = Color.lerp(circuit.nightMode ? const Color(0xFF0F172B) : const Color(0xFF233245), circuit.skyBottom, 0.24)!,
    );

    // Architectural Main Grandstand with GPU Crowd Texture + VIP Glass Paddock Club
    final double gsX = ((w * 0.03 + engine.horizonPan * 0.50) % (w * 1.6)) - w * 0.3;
    final double gsW = w * 0.62;
    final double gsTop = horizonY - 52;
    final Rect gsRect = Rect.fromLTWH(gsX, gsTop, gsW, 52);
    canvas.drawRect(
      gsRect,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: circuit.nightMode
              ? const [Color(0xFF1A243B), Color(0xFF0B101B)]
              : const [Color(0xFF4F5A6B), Color(0xFF222833)],
        ).createShader(gsRect),
    );
    // Textured Spectator Crowd inside Grandstand!
    if (ProTextures.crowdShader != null) {
      canvas.save();
      final Rect crowdArea = Rect.fromLTWH(gsX + 4, gsTop + 14, gsW - 8, 36);
      canvas.clipRect(crowdArea);
      canvas.translate(gsX, gsTop + 14);
      canvas.drawRect(
        Rect.fromLTWH(0, 0, gsW, 36),
        Paint()..shader = ProTextures.crowdShader,
      );
      canvas.restore();
    }
    // VIP Glass Balcony
    canvas.drawRect(
      Rect.fromLTWH(gsX + 4, gsTop + 3, gsW - 8, 9),
      Paint()..color = circuit.nightMode ? const Color(0xAA40C4FF) : const Color(0x70B3E5FC),
    );
    // Roof Canopy
    canvas.drawRect(
      Rect.fromLTWH(gsX - 12, gsTop - 8, gsW + 24, 9),
      Paint()..color = circuit.nightMode ? const Color(0xFF334366) : const Color(0xFF8F9BAB),
    );
    final Paint pillarPaint = Paint()..color = const Color(0xFF171C26)..strokeWidth = 3.2;
    for (int p = 0; p <= 7; p++) {
      final double px = gsX + (gsW / 7) * p;
      canvas.drawLine(Offset(px, gsTop), Offset(px, horizonY), pillarPaint);
    }
  }

  void _drawStartGantry(
    Canvas canvas,
    double s1,
    double y1,
    double z1,
    double roadHalfW,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
  ) {
    final Offset bL = _project(-roadHalfW - 0.85 + s1, y1, z1, w, horizonY, fovMult);
    final Offset bR = _project(roadHalfW + 0.85 + s1, y1, z1, w, horizonY, fovMult);
    final Offset tL = _project(-roadHalfW - 0.85 + s1, y1 + 3.6, z1, w, horizonY, fovMult);
    final Offset tR = _project(roadHalfW + 0.85 + s1, y1 + 3.6, z1, w, horizonY, fovMult);
    final double beamH = max(5.0, 58.0 / z1);

    final Paint postPaint = Paint()
      ..isAntiAlias = true
      ..color = Color.lerp(const Color(0xFF1B212C), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(3.0, 26.0 / z1);
    canvas.drawLine(bL, tL, postPaint);
    canvas.drawLine(bR, tR, postPaint);

    final Rect bridge = Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tR.dy + beamH * 0.5);
    canvas.drawRect(bridge, Paint()..color = Color.lerp(const Color(0xFF101520), circuit.skyBottom, fogMix)!);
    canvas.drawRect(
      Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tL.dy - beamH * 0.22),
      Paint()..color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix)!,
    );
  }

  void _drawTracksideProp(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    final Offset top = _project(x, y1 + 4.0, z, w, horizonY, fovMult);
    final double ph = max(8.0, base.dy - top.dy);
    final double pw = max(6.0, ph * 0.52);

    if (circuit.propStyle == PropStyle.palms) {
      canvas.drawLine(
        base,
        top,
        Paint()
          ..isAntiAlias = true
          ..color = Color.lerp(const Color(0xFF5D4037), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(2.2, pw * 0.16),
      );
      final Paint frondPaint = Paint()
        ..isAntiAlias = true
        ..color = Color.lerp(circuit.nightMode ? const Color(0xFF1C4F30) : const Color(0xFF2B6E33), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.0, pw * 0.14)
        ..strokeCap = StrokeCap.round;
      for (int a = 0; a < 7; a++) {
        final double ang = -pi + (a * pi / 6);
        canvas.drawLine(top, Offset(top.dx + cos(ang) * pw * 0.95, top.dy + sin(ang) * pw * 0.45 + 4), frondPaint);
      }
    } else if (circuit.propStyle == PropStyle.skyline) {
      final Rect bldg = Rect.fromLTWH(top.dx - pw * 0.65, top.dy - ph * 0.35, pw * 1.3, ph * 1.35);
      canvas.drawRect(
        bldg,
        Paint()..color = Color.lerp(circuit.nightMode ? const Color(0xFF161E33) : const Color(0xFF384257), circuit.skyBottom, fogMix)!,
      );
      if (pw > 14) {
        final Paint win = Paint()..color = circuit.nightMode ? const Color(0xCC00E5FF) : const Color(0x66FFF0A6);
        for (int r = 0; r < 3; r++) {
          canvas.drawRect(Rect.fromLTWH(bldg.left + pw * 0.2, bldg.top + ph * (0.2 + r * 0.25), pw * 0.9, ph * 0.09), win);
        }
      }
    } else if (circuit.propStyle == PropStyle.trees) {
      canvas.drawLine(
        base,
        Offset(top.dx, base.dy - ph * 0.42),
        Paint()..color = Color.lerp(const Color(0xFF4E342E), circuit.skyBottom, fogMix)!..strokeWidth = max(2.2, pw * 0.18),
      );
      final Color leafDark = Color.lerp(const Color(0xFF18441E), circuit.skyBottom, fogMix)!;
      final Color leafLight = Color.lerp(const Color(0xFF35783A), circuit.skyBottom, fogMix)!;
      canvas.drawCircle(Offset(top.dx, base.dy - ph * 0.65), pw * 0.56, Paint()..isAntiAlias = true..color = leafDark);
      canvas.drawCircle(Offset(top.dx - pw * 0.15, base.dy - ph * 0.72), pw * 0.36, Paint()..isAntiAlias = true..color = leafLight);
    } else {
      canvas.drawLine(
        base,
        top,
        Paint()..color = Color.lerp(const Color(0xFF90A4AE), circuit.skyBottom, fogMix)!..strokeWidth = max(1.8, pw * 0.12),
      );
      if (circuit.nightMode) {
        final double glowR = max(6.0, pw * 0.55);
        canvas.drawCircle(
          top,
          glowR,
          Paint()
            ..shader = const RadialGradient(
              colors: [Color(0xEEFFFFFF), Color(0x44FFFDE7), Color(0x00FFFDE7)],
            ).createShader(Rect.fromCircle(center: top, radius: glowR)),
        );
      }
    }
  }

  /// Anatomically detailed 3D-perspective modern F1 rival car (shifts sidepod & front-wheel depth with parallax!)
  void _drawRivalF1CarPro(Canvas canvas, Offset pos, double sc, double parallax, AiDriver ai) {
    final double cw = (sc * 1.44).clamp(11.0, 250.0).toDouble();
    final double ch = (sc * 0.62).clamp(5.5, 108.0).toDouble();
    final double shift3d = -parallax * cw * 0.16;

    // 1. Hardware-Accelerated Soft Contact Shadow (RadialGradient = silky 120fps)
    final Rect shadRect = Rect.fromCenter(center: Offset(pos.dx, pos.dy + ch * 0.05), width: cw * 1.72, height: ch * 0.46);
    canvas.drawOval(
      shadRect,
      Paint()
        ..shader = const RadialGradient(
          colors: [Color(0xDD000000), Color(0x88000000), Color(0x00000000)],
        ).createShader(shadRect),
    );

    // 2. Peek of Front Tires in 3D Perspective ahead of rear axle!
    if (cw > 26) {
      final double ftW = cw * 0.19;
      final double ftH = ch * 0.62;
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(pos.dx + shift3d * 1.3 - cw * 0.58, pos.dy - ch * 0.92, ftW, ftH),
          Radius.circular(cw * 0.04),
        ),
        Paint()..isAntiAlias = true..color = const Color(0xFF14171D),
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(pos.dx + shift3d * 1.3 + cw * 0.39, pos.dy - ch * 0.92, ftW, ftH),
          Radius.circular(cw * 0.04),
        ),
        Paint()..isAntiAlias = true..color = const Color(0xFF14171D),
      );
    }

    // 3. Carbon Floor Plank + Venturi Edge Wings
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTWH(pos.dx - cw * 0.54, pos.dy - ch * 0.24, cw * 1.08, ch * 0.22),
        Radius.circular(cw * 0.03),
      ),
      Paint()..isAntiAlias = true..color = const Color(0xFF11141B),
    );

    // 4. Sculpted Wide Rear Slick Tires with 3D Cylindrical Shading + Outer Rim Accent
    final RRect tireL = RRect.fromRectAndRadius(
      Rect.fromLTWH(pos.dx - cw * 0.76, pos.dy - ch * 0.98, cw * 0.31, ch * 0.98),
      Radius.circular(cw * 0.06),
    );
    final RRect tireR = RRect.fromRectAndRadius(
      Rect.fromLTWH(pos.dx + cw * 0.45, pos.dy - ch * 0.98, cw * 0.31, ch * 0.98),
      Radius.circular(cw * 0.06),
    );
    canvas.drawRRect(
      tireL,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          stops: [0.0, 0.25, 0.55, 1.0],
          colors: [Color(0xFF090B0E), Color(0xFF282E38), Color(0xFF3C4452), Color(0xFF0D1015)],
        ).createShader(tireL.outerRect),
    );
    canvas.drawRRect(
      tireR,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          stops: [0.0, 0.45, 0.75, 1.0],
          colors: [Color(0xFF0D1015), Color(0xFF3C4452), Color(0xFF282E38), Color(0xFF090B0E)],
        ).createShader(tireR.outerRect),
    );
    // Pirelli sidewall stripe hint on outer edge of tires
    if (cw > 42) {
      final Paint rimHint = Paint()..color = const Color(0xBBE10600)..strokeWidth = max(1.0, cw * 0.015);
      canvas.drawLine(Offset(tireL.left + 1.5, tireL.top + ch * 0.22), Offset(tireL.left + 1.5, tireL.bottom - ch * 0.22), rimHint);
      canvas.drawLine(Offset(tireR.right - 1.5, tireR.top + ch * 0.22), Offset(tireR.right - 1.5, tireR.bottom - ch * 0.22), rimHint);
    }

    // 5. Rear Multi-Link Suspension Arms + Carbon Venturi Diffuser + Metallic Exhaust Pipe
    final Paint suspP = Paint()..isAntiAlias = true..color = const Color(0xFF1A1F29)..strokeWidth = max(1.2, ch * 0.08);
    canvas.drawLine(Offset(pos.dx - cw * 0.46, pos.dy - ch * 0.52), Offset(pos.dx - cw * 0.22, pos.dy - ch * 0.48), suspP);
    canvas.drawLine(Offset(pos.dx + cw * 0.46, pos.dy - ch * 0.52), Offset(pos.dx + cw * 0.22, pos.dy - ch * 0.48), suspP);

    final Rect diffRect = Rect.fromLTWH(pos.dx - cw * 0.40, pos.dy - ch * 0.38, cw * 0.80, ch * 0.36);
    canvas.drawRect(diffRect, Paint()..color = const Color(0xFF12151C));
    if (cw > 34) {
      final Paint strake = Paint()..color = const Color(0xFF384152)..strokeWidth = max(1.0, cw * 0.014);
      canvas.drawLine(Offset(pos.dx - cw * 0.24, diffRect.top), Offset(pos.dx - cw * 0.24, diffRect.bottom), strake);
      canvas.drawLine(Offset(pos.dx + cw * 0.24, diffRect.top), Offset(pos.dx + cw * 0.24, diffRect.bottom), strake);
      // Central metallic exhaust pipe
      canvas.drawCircle(Offset(pos.dx, pos.dy - ch * 0.56), cw * 0.055, Paint()..color = const Color(0xFF788596));
      canvas.drawCircle(Offset(pos.dx, pos.dy - ch * 0.56), cw * 0.032, Paint()..color = const Color(0xFF0A0C10));
    }

    // 6. Sculpted Coke-Bottle Sidepods & Glossy Engine Cover (shifts subtly in 3D!)
    final Path sidepods = Path()
      ..moveTo(pos.dx - cw * 0.48, pos.dy - ch * 0.30)
      ..quadraticBezierTo(pos.dx - cw * 0.46 + shift3d * 0.4, pos.dy - ch * 0.82, pos.dx - cw * 0.28 + shift3d * 0.6, pos.dy - ch * 1.00)
      ..quadraticBezierTo(pos.dx + shift3d * 0.7, pos.dy - ch * 1.24, pos.dx + cw * 0.28 + shift3d * 0.6, pos.dy - ch * 1.00)
      ..quadraticBezierTo(pos.dx + cw * 0.46 + shift3d * 0.4, pos.dy - ch * 0.82, pos.dx + cw * 0.48, pos.dy - ch * 0.30)
      ..close();
    canvas.drawPath(
      sidepods,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.35, 0.82, 1.0],
          colors: [ai.bodyHighlight, ai.bodyColor, Color.lerp(ai.bodyColor, Colors.black, 0.45)!, const Color(0xFF090B0F)],
        ).createShader(Rect.fromLTWH(pos.dx - cw * 0.48, pos.dy - ch * 1.24, cw * 0.96, ch * 0.96)),
    );

    // Specular sky reflection arc across engine cover shoulders
    if (cw > 36) {
      canvas.drawPath(
        Path()
          ..moveTo(pos.dx - cw * 0.26 + shift3d * 0.6, pos.dy - ch * 0.96)
          ..quadraticBezierTo(pos.dx + shift3d * 0.7, pos.dy - ch * 1.15, pos.dx + cw * 0.26 + shift3d * 0.6, pos.dy - ch * 0.96),
        Paint()
          ..isAntiAlias = true
          ..color = const Color(0x66FFFFFF)
          ..style = PaintingStyle.stroke
          ..strokeWidth = max(1.0, cw * 0.018),
      );
    }

    // 7. Driver Helmet + Halo Hoop + Sculpted Airbox + Shark Fin + T-Cam
    final double topX = pos.dx + shift3d * 0.9;
    canvas.drawCircle(Offset(topX, pos.dy - ch * 1.20), cw * 0.105, Paint()..isAntiAlias = true..color = ai.helmetColor);
    // Halo arc around helmet
    if (cw > 36) {
      canvas.drawArc(
        Rect.fromCenter(center: Offset(topX, pos.dy - ch * 1.16), width: cw * 0.32, height: ch * 0.44),
        pi,
        pi,
        false,
        Paint()..isAntiAlias = true..color = const Color(0xFF181C24)..style = PaintingStyle.stroke..strokeWidth = max(1.5, cw * 0.025),
      );
    }
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(topX - cw * 0.085, pos.dy - ch * 1.50, cw * 0.17, ch * 0.36), Radius.circular(cw * 0.04)),
      Paint()..isAntiAlias = true..color = ai.bodyColor,
    );
    // T-Cam bar
    canvas.drawRect(Rect.fromLTWH(topX - cw * 0.14, pos.dy - ch * 1.56, cw * 0.28, ch * 0.065), Paint()..color = const Color(0xFF171A21));

    // 8. Dual-Element Sculpted Rear Wing (Mainplane + Curved DRS Flap + Beam Wing + Endplates)
    // Lower Beam Wing
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.44, pos.dy - ch * 0.74, cw * 0.88, ch * 0.11), Paint()..color = const Color(0xFF181C24));
    // Central Swan-Neck Rear Wing Pillar
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.03, pos.dy - ch * 1.24, cw * 0.06, ch * 0.60), Paint()..color = const Color(0xFF161A22));
    // Upper Rear Wing Mainplane + DRS Flap
    final RRect wingTop = RRect.fromRectAndRadius(
      Rect.fromLTWH(pos.dx - cw * 0.50, pos.dy - ch * 1.32, cw * 1.00, ch * 0.24),
      Radius.circular(cw * 0.025),
    );
    canvas.drawRRect(
      wingTop,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color.lerp(ai.wingColor, Colors.white, 0.22)!, ai.wingColor, Color.lerp(ai.wingColor, Colors.black, 0.35)!],
        ).createShader(wingTop.outerRect),
    );
    // DRS Slot Gap
    canvas.drawLine(
      Offset(wingTop.left + 2, wingTop.center.dy),
      Offset(wingTop.right - 2, wingTop.center.dy),
      Paint()..color = const Color(0xAA000000)..strokeWidth = max(1.0, ch * 0.045),
    );
    // Curved Rear Wing Endplates
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx - cw * 0.54, pos.dy - ch * 1.36, cw * 0.065, ch * 0.58), Radius.circular(cw * 0.02)),
      Paint()..isAntiAlias = true..color = const Color(0xFF171B24),
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx + cw * 0.475, pos.dy - ch * 1.36, cw * 0.065, ch * 0.58), Radius.circular(cw * 0.02)),
      Paint()..isAntiAlias = true..color = const Color(0xFF171B24),
    );

    // 9. Pulsing Red FIA ERS Rain Light (RadialGradient glow — fast & bright!)
    final Offset lightC = Offset(pos.dx, pos.dy - ch * 0.38);
    final double lr = max(3.5, cw * 0.11);
    canvas.drawCircle(
      lightC,
      lr,
      Paint()
        ..shader = const RadialGradient(
          colors: [Color(0xEEFF3D5A), Color(0x55FF1744), Color(0x00FF1744)],
        ).createShader(Rect.fromCircle(center: lightC, radius: lr)),
    );
    canvas.drawRect(Rect.fromCenter(center: lightC, width: cw * 0.075, height: ch * 0.18), Paint()..color = const Color(0xFFFF526E));

    // 10. Crisp Broadcast 3-Letter Driver Tag
    if (cw > 24) {
      final double fz = (cw * 0.13).clamp(9.0, 13.0).toDouble();
      final TextPainter tp = TextPainter(
        text: TextSpan(
          text: ai.code,
          style: TextStyle(color: Colors.white, fontSize: fz, fontWeight: FontWeight.w900, letterSpacing: 0.5),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      final double bx = pos.dx - tp.width * 0.5 - 5;
      final double by = pos.dy - ch * 1.72 - tp.height;
      canvas.drawRRect(
        RRect.fromRectAndRadius(Rect.fromLTWH(bx, by - 1, tp.width + 10, tp.height + 2), const Radius.circular(4)),
        Paint()..color = const Color(0xBB070B12),
      );
      canvas.drawRect(Rect.fromLTWH(bx, by - 1, 2.8, tp.height + 2), Paint()..color = ai.bodyColor);
      tp.paint(canvas, Offset(bx + 5, by));
    }
  }

  void _drawCockpitPro(Canvas canvas, double w, double h, CircuitInfo circuit) {
    final TeamLivery livery = engine.livery;
    final double cx = w * 0.5;
    final double offTrackShake = engine.carX.abs() > 1.02 ? (sin(engine.playerDist * 2.8) * 4.5) : 0.0;
    final double vib = sin(engine.playerDist * 0.9) * (engine.speedKmh / 320.0) * 1.3 + offTrackShake + engine.smoothPitch * 2.5;

    final Paint carbonPaint = ProTextures.carbonShader != null
        ? (Paint()..isAntiAlias = true..shader = ProTextures.carbonShader..filterQuality = FilterQuality.high)
        : (Paint()..isAntiAlias = true..color = const Color(0xFF15181F));

    final double wheelShift = engine.steerAngle * 18.0;

    // 1. Sculpted Aerodynamic Front Wing Endplates peeking ahead of tires
    final Paint wingPaint = Paint()
      ..isAntiAlias = true
      ..shader = LinearGradient(colors: [livery.primaryLight, livery.primaryDark]).createShader(Rect.fromLTWH(0, h * 0.57, w, 40));
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.075 + wheelShift * 0.65, h * 0.595 + vib, w * 0.10, 11), const Radius.circular(3)),
      wingPaint,
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.825 + wheelShift * 0.65, h * 0.595 + vib, w * 0.10, 11), const Radius.circular(3)),
      wingPaint,
    );

    // 2. High-Resolution 3D Front Slick Tires + Ground-Effect Wheel Brows + Glowing Brakes
    _drawFrontTirePro(canvas, Offset(w * 0.172 + wheelShift, h * 0.72 + vib), w * 0.16, h * 0.315, true);
    _drawFrontTirePro(canvas, Offset(w * 0.828 + wheelShift, h * 0.72 + vib), w * 0.16, h * 0.315, false);

    // 3. Multi-Link Carbon Suspension Wishbones + Titanium Pushrod
    final Paint suspUpper = Paint()..isAntiAlias = true..color = const Color(0xFF1D222C)..strokeWidth = 6.5..strokeCap = StrokeCap.round;
    final Paint suspLower = Paint()..isAntiAlias = true..color = const Color(0xFF0E1117)..strokeWidth = 8.4..strokeCap = StrokeCap.round;
    final Paint pushrod = Paint()..isAntiAlias = true..color = const Color(0xFF5A6880)..strokeWidth = 3.2..strokeCap = StrokeCap.round;

    canvas.drawLine(Offset(w * 0.22 + wheelShift * 0.5, h * 0.675 + vib), Offset(w * 0.38, h * 0.735 + vib), suspUpper);
    canvas.drawLine(Offset(w * 0.23 + wheelShift * 0.5, h * 0.765 + vib), Offset(w * 0.40, h * 0.795 + vib), suspLower);
    canvas.drawLine(Offset(w * 0.24 + wheelShift * 0.5, h * 0.745 + vib), Offset(w * 0.39, h * 0.695 + vib), pushrod);

    canvas.drawLine(Offset(w * 0.78 + wheelShift * 0.5, h * 0.675 + vib), Offset(w * 0.62, h * 0.735 + vib), suspUpper);
    canvas.drawLine(Offset(w * 0.77 + wheelShift * 0.5, h * 0.765 + vib), Offset(w * 0.60, h * 0.795 + vib), suspLower);
    canvas.drawLine(Offset(w * 0.76 + wheelShift * 0.5, h * 0.745 + vib), Offset(w * 0.61, h * 0.695 + vib), pushrod);

    // 4. Sculpted Glossy Clearcoat Monocoque Nose & Side Coamings + Pitot Sensor Mast
    final Path cowling = Path()
      ..moveTo(0, h * 0.695 + vib)
      ..quadraticBezierTo(w * 0.20, h * 0.605 + vib, w * 0.36, h * 0.725 + vib)
      ..lineTo(w * 0.64, h * 0.725 + vib)
      ..quadraticBezierTo(w * 0.80, h * 0.605 + vib, w, h * 0.695 + vib)
      ..lineTo(w, h)
      ..lineTo(0, h)
      ..close();
    canvas.drawPath(
      cowling,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.18, 0.54, 1.0],
          colors: [livery.primaryLight, livery.primary, livery.primaryDark, const Color(0xFF080A0E)],
        ).createShader(Rect.fromLTWH(0, h * 0.60, w, h * 0.40)),
    );

    // Metallic clearcoat specular highlight along sculpted shoulders
    canvas.drawPath(
      Path()
        ..moveTo(0, h * 0.695 + vib)
        ..quadraticBezierTo(w * 0.20, h * 0.605 + vib, w * 0.36, h * 0.725 + vib)
        ..lineTo(w * 0.64, h * 0.725 + vib)
        ..quadraticBezierTo(w * 0.80, h * 0.605 + vib, w, h * 0.695 + vib),
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0xAAFFFFFF)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.6,
    );

    // Secondary livery pin-stripes
    canvas.drawPath(
      Path()
        ..moveTo(w * 0.03, h * 0.71 + vib)
        ..quadraticBezierTo(w * 0.20, h * 0.64 + vib, w * 0.34, h * 0.74 + vib),
      Paint()..isAntiAlias = true..color = livery.secondary.withAlpha(210)..style = PaintingStyle.stroke..strokeWidth = 3.2,
    );
    canvas.drawPath(
      Path()
        ..moveTo(w * 0.97, h * 0.71 + vib)
        ..quadraticBezierTo(w * 0.80, h * 0.64 + vib, w * 0.66, h * 0.74 + vib),
      Paint()..isAntiAlias = true..color = livery.secondary.withAlpha(210)..style = PaintingStyle.stroke..strokeWidth = 3.2,
    );

    // Aerodynamic Side Mirrors with Sky Reflection + Live Rival Proximity Dot
    _drawSideMirrorPro(canvas, Offset(w * 0.26, h * 0.65 + vib), true, engine.rivalCloseLeft, circuit);
    _drawSideMirrorPro(canvas, Offset(w * 0.74, h * 0.65 + vib), false, engine.rivalCloseRight, circuit);

    // Woven Carbon-Fiber Cockpit Tub
    final Path tub = Path()
      ..moveTo(w * 0.23, h * 0.745 + vib)
      ..lineTo(w * 0.77, h * 0.745 + vib)
      ..lineTo(w * 0.85, h)
      ..lineTo(w * 0.15, h)
      ..close();
    canvas.drawPath(tub, carbonPaint);
    canvas.drawPath(
      tub,
      Paint()
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0xCC000000), Color(0x35000000)],
        ).createShader(Rect.fromLTWH(w * 0.15, h * 0.745, w * 0.70, h * 0.255)),
    );

    // 5. Photorealistic 3D Titanium Halo (Top Arch + Cylindrical Pillar + Central Mounting Pod)
    final Path haloArch = Path()
      ..moveTo(0, 0)
      ..lineTo(w, 0)
      ..lineTo(w, h * 0.145)
      ..quadraticBezierTo(cx, h * 0.012, 0, h * 0.145)
      ..close();
    canvas.drawPath(
      haloArch,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [const Color(0xFF080A0F), livery.primaryDark, livery.primary],
        ).createShader(Rect.fromLTWH(0, 0, w, h * 0.155)),
    );

    final Path pillar = Path()
      ..moveTo(cx - 26, h * 0.04)
      ..lineTo(cx + 26, h * 0.04)
      ..lineTo(cx + 12, h * 0.73 + vib)
      ..lineTo(cx - 12, h * 0.73 + vib)
      ..close();
    canvas.drawPath(
      pillar,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          stops: const [0.0, 0.24, 0.50, 0.76, 1.0],
          colors: [
            const Color(0xFF090B0F),
            livery.primaryDark,
            livery.primaryLight,
            livery.primaryDark,
            const Color(0xFF07090D),
          ],
        ).createShader(Rect.fromLTWH(cx - 26, 0, 52, h * 0.74)),
    );

    // Central Halo Camera/Mounting Badge (just like real F1!)
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(cx, h * 0.16), width: 22, height: 28), const Radius.circular(6)),
      Paint()..isAntiAlias = true..color = const Color(0xFF12151C),
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(cx, h * 0.16), width: 16, height: 22), const Radius.circular(4)),
      Paint()..isAntiAlias = true..color = livery.primaryDark..style = PaintingStyle.stroke..strokeWidth = 1.6,
    );

    // 6. Pro-Grade Sculpted F1 Steering Wheel + Paddles + Contoured Gloved Hands
    _drawButterflyWheelPro(canvas, cx, h * 0.855 + vib, w, h, carbonPaint);
  }

  void _drawSideMirrorPro(Canvas canvas, Offset pos, bool isLeft, bool rivalBehind, CircuitInfo circuit) {
    final TeamLivery livery = engine.livery;
    final double dir = isLeft ? -1.0 : 1.0;
    canvas.drawLine(
      Offset(pos.dx - dir * 10, pos.dy + 17),
      Offset(pos.dx, pos.dy + 4),
      Paint()..isAntiAlias = true..color = const Color(0xFF141720)..strokeWidth = 4.6,
    );
    final RRect shell = RRect.fromRectAndRadius(
      Rect.fromCenter(center: pos, width: 50, height: 20),
      const Radius.circular(9),
    );
    canvas.drawRRect(
      shell,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [livery.primaryLight, livery.primaryDark],
        ).createShader(shell.outerRect),
    );
    final Rect glass = Rect.fromCenter(center: Offset(pos.dx, pos.dy + 1), width: 40, height: 13);
    canvas.drawRRect(
      RRect.fromRectAndRadius(glass, const Radius.circular(5)),
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [circuit.skyTop, circuit.skyBottom, const Color(0xFF282D38)],
        ).createShader(glass),
    );
    if (rivalBehind) {
      canvas.drawCircle(Offset(pos.dx, pos.dy + 3), 3.4, Paint()..color = const Color(0xFFFF1744));
    }
  }

  void _drawFrontTirePro(Canvas canvas, Offset center, double tw, double th, bool isLeft) {
    final RRect tireRect = RRect.fromRectAndRadius(
      Rect.fromCenter(center: center, width: tw, height: th),
      const Radius.circular(24),
    );

    // Hardware-accelerated Glowing Carbon-Ceramic Brake Disc when braking!
    if (engine.brakeHeld && engine.speedKmh > 55) {
      final Offset discCenter = Offset(center.dx + (isLeft ? tw * 0.48 : -tw * 0.48), center.dy);
      final double dr = tw * 0.36;
      canvas.drawCircle(
        discCenter,
        dr,
        Paint()
          ..shader = const RadialGradient(
            colors: [Color(0xEEFF8A00), Color(0xAAFF3D00), Color(0x00FF3D00)],
          ).createShader(Rect.fromCircle(center: discCenter, radius: dr)),
      );
    }

    // 3D Cylindrical Rubber Shading
    canvas.drawRRect(
      tireRect,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          stops: [0.0, 0.18, 0.48, 0.78, 1.0],
          colors: [
            Color(0xFF07080B),
            Color(0xFF212630),
            Color(0xFF424A59),
            Color(0xFF1D222B),
            Color(0xFF07080B),
          ],
        ).createShader(tireRect.outerRect),
    );

    // Smooth Rotating Tire Tread Grain
    if (engine.speedKmh > 5) {
      final double phase = (engine.playerDist * 0.75) % 1.0;
      final Paint bandPaint = Paint()..color = const Color(0x30000000)..strokeWidth = 4.2;
      for (int b = 0; b < 5; b++) {
        final double yFrac = ((b * 0.2 + phase) % 1.0) - 0.5;
        final double yy = center.dy + yFrac * th * 0.86;
        canvas.drawLine(Offset(center.dx - tw * 0.36, yy), Offset(center.dx + tw * 0.36, yy), bandPaint);
      }
    }

    // Curved Carbon-Fiber Ground-Effect Wheel Brow Winglet (authentic modern F1 look!)
    final double dir = isLeft ? 1.0 : -1.0;
    canvas.drawArc(
      Rect.fromCenter(center: Offset(center.dx + dir * tw * 0.18, center.dy - th * 0.04), width: tw * 0.85, height: th * 0.96),
      isLeft ? -pi * 0.34 : pi * 0.66,
      pi * 0.68,
      false,
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0xFF151922)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 6.5
        ..strokeCap = StrokeCap.round,
    );

    // Crisp Pirelli P-Zero Red Sidewall Ring
    canvas.drawArc(
      Rect.fromCenter(
        center: Offset(center.dx + dir * tw * 0.24, center.dy),
        width: tw * 0.47,
        height: th * 0.70,
      ),
      -pi * 0.37,
      pi * 0.74,
      false,
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0xFFE10600)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 4.0,
    );
  }

  void _drawButterflyWheelPro(
    Canvas canvas,
    double cx,
    double cy,
    double w,
    double h,
    Paint carbonPaint,
  ) {
    final bool ersOn = engine.ersActive;
    final int rpm = engine.rpm;
    final int gear = engine.gear;

    canvas.save();
    canvas.translate(cx, cy);
    canvas.rotate(engine.steerAngle * 0.46 + engine.spinYaw * 0.5);

    final double swW = (w * 0.40).clamp(228.0, 360.0).toDouble();
    final double swH = (h * 0.325).clamp(126.0, 192.0).toDouble();

    // Carbon Shift Paddles peeking behind upper corners of wheel
    final Paint paddlePaint = Paint()..isAntiAlias = true..color = const Color(0xFF28303D);
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(-swW * 0.53, -swH * 0.26, swW * 0.14, swH * 0.14), const Radius.circular(6)),
      paddlePaint,
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(swW * 0.39, -swH * 0.26, swW * 0.14, swH * 0.14), const Radius.circular(6)),
      paddlePaint,
    );

    // Sculpted Butterfly Wheel Frame
    final Path wheelShape = Path()
      ..moveTo(-swW * 0.42, -swH * 0.47)
      ..lineTo(-swW * 0.24, -swH * 0.47)
      ..lineTo(-swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.24, -swH * 0.47)
      ..lineTo(swW * 0.42, -swH * 0.47)
      ..quadraticBezierTo(swW * 0.52, -swH * 0.45, swW * 0.50, -swH * 0.12)
      ..lineTo(swW * 0.47, swH * 0.37)
      ..quadraticBezierTo(swW * 0.44, swH * 0.49, swW * 0.24, swH * 0.47)
      ..lineTo(-swW * 0.24, swH * 0.47)
      ..quadraticBezierTo(-swW * 0.44, swH * 0.49, -swW * 0.47, swH * 0.37)
      ..lineTo(-swW * 0.50, -swH * 0.12)
      ..quadraticBezierTo(-swW * 0.52, -swH * 0.45, -swW * 0.42, -swH * 0.47)
      ..close();

    canvas.drawPath(wheelShape, carbonPaint);
    canvas.drawPath(
      wheelShape,
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0xFF5D6B82)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4,
    );

    // 15 Progressive Glowing RPM Shift LEDs (fast RadialGradient glow!)
    final double rpmRatio = ((rpm - 5800) / 8400.0).clamp(0.0, 1.0).toDouble();
    const int ledCount = 15;
    for (int i = 0; i < ledCount; i++) {
      final bool lit = (i / ledCount) < rpmRatio;
      final Color ledColor = i < 5
          ? const Color(0xFF00E676)
          : (i < 10 ? const Color(0xFFFF1744) : const Color(0xFF2979FF));
      final double lx = -swW * 0.22 + (i * (swW * 0.44 / (ledCount - 1)));
      final Offset lc = Offset(lx, -swH * 0.29);
      if (lit) {
        canvas.drawCircle(
          lc,
          6.5,
          Paint()
            ..shader = RadialGradient(
              colors: [ledColor.withAlpha(185), ledColor.withAlpha(0)],
            ).createShader(Rect.fromCircle(center: lc, radius: 6.5)),
        );
      }
      canvas.drawCircle(lc, 2.8, Paint()..isAntiAlias = true..color = lit ? ledColor : const Color(0xFF202530));
    }

    // Recessed Anti-Glare OLED Telemetry Screen
    final Rect lcdRect = Rect.fromCenter(center: Offset(0, -swH * 0.01), width: swW * 0.45, height: swH * 0.45);
    canvas.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)), Paint()..color = const Color(0xFF04060A));
    canvas.drawRRect(
      RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)),
      Paint()
        ..isAntiAlias = true
        ..color = ersOn ? const Color(0xFF00E5FF) : const Color(0xFF425169)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.7,
    );

    _drawCenteredText(canvas, '$gear', Offset(0, -swH * 0.025), swH * 0.225, Colors.white, FontWeight.w900);
    _drawCenteredText(canvas, '${engine.speedKmh.toInt()}', Offset(-swW * 0.145, -swH * 0.13), swH * 0.102, const Color(0xFF00E676), FontWeight.w900);
    _drawCenteredText(canvas, 'P${engine.currentPosition}', Offset(swW * 0.145, -swH * 0.13), swH * 0.09, const Color(0xFFFFD54F), FontWeight.w900);
    _drawCenteredText(canvas, 'L${engine.currentLap}/5', Offset(swW * 0.145, swH * 0.04), swH * 0.072, Colors.white70, FontWeight.bold);
    _drawCenteredText(
      canvas,
      ersOn ? 'ERS BOOST' : '$rpm RPM',
      Offset(0, swH * 0.11),
      swH * 0.075,
      ersOn ? const Color(0xFF00E5FF) : const Color(0xFF94A3B8),
      FontWeight.bold,
    );

    final double barW = lcdRect.width - 12;
    canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 6, barW, 3.4), Paint()..color = const Color(0xFF1E293B));
    canvas.drawRect(
      Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 6, barW * (engine.ersCharge / 100.0), 3.4),
      Paint()..color = ersOn ? const Color(0xFF00E5FF) : const Color(0xFFFFD600),
    );

    // 3 Anodized Knurled Rotary Dials with Brushed Titanium Bezels
    const List<Color> knobColors = [Color(0xFFE53935), Color(0xFF43A047), Color(0xFFFFB300)];
    for (int k = 0; k < 3; k++) {
      final double kx = (k - 1) * (swW * 0.115);
      final Offset kc = Offset(kx, swH * 0.34);
      canvas.drawCircle(
        kc,
        swH * 0.088,
        ProTextures.brushedMetalShader != null
            ? (Paint()..isAntiAlias = true..shader = ProTextures.brushedMetalShader)
            : (Paint()..isAntiAlias = true..color = const Color(0xFF94A3B8)),
      );
      canvas.drawCircle(kc, swH * 0.072, Paint()..isAntiAlias = true..color = knobColors[k]);
      canvas.drawCircle(kc, swH * 0.032, Paint()..isAntiAlias = true..color = const Color(0xFF13171F));
    }

    // Illuminated Tactile Side Buttons
    _drawWheelButton(canvas, Offset(-swW * 0.33, -swH * 0.24), const Color(0xFF29B6F6));
    _drawWheelButton(canvas, Offset(swW * 0.33, -swH * 0.24), const Color(0xFFFFCA28));
    _drawWheelButton(canvas, Offset(-swW * 0.31, -swH * 0.04), const Color(0xFFEF5350));
    _drawWheelButton(canvas, Offset(swW * 0.31, -swH * 0.04), const Color(0xFF66BB6A));
    _drawWheelButton(canvas, Offset(-swW * 0.29, swH * 0.16), const Color(0xFFAB47BC));
    _drawWheelButton(canvas, Offset(swW * 0.29, swH * 0.16), const Color(0xFFFF7043));

    // Contoured Multi-Shaded Racing Gloves
    _drawRacingGlovePro(canvas, swW, swH, true);
    _drawRacingGlovePro(canvas, swW, swH, false);

    canvas.restore();
  }

  void _drawWheelButton(Canvas canvas, Offset center, Color color) {
    canvas.drawCircle(center, 6.4, Paint()..isAntiAlias = true..color = const Color(0xFF0D1016));
    canvas.drawCircle(center, 4.6, Paint()..isAntiAlias = true..color = color);
    canvas.drawCircle(Offset(center.dx - 1.3, center.dy - 1.3), 1.5, Paint()..isAntiAlias = true..color = const Color(0xAAFFFFFF));
  }

  void _drawRacingGlovePro(Canvas canvas, double swW, double swH, bool isLeft) {
    final TeamLivery livery = engine.livery;
    final double s = isLeft ? -1.0 : 1.0;
    final Rect palmRect = Rect.fromCenter(
      center: Offset(s * swW * 0.45, swH * 0.16),
      width: swW * 0.23,
      height: swH * 0.64,
    );
    final Paint gloveShader = Paint()
      ..isAntiAlias = true
      ..shader = LinearGradient(
        begin: isLeft ? Alignment.centerLeft : Alignment.centerRight,
        end: isLeft ? Alignment.centerRight : Alignment.centerLeft,
        colors: [
          Color.lerp(livery.gloveColor, Colors.black, 0.38)!,
          livery.gloveColor,
          Color.lerp(livery.gloveColor, Colors.white, 0.18)!,
        ],
      ).createShader(palmRect);

    canvas.drawRRect(RRect.fromRectAndRadius(palmRect, const Radius.circular(20)), gloveShader);

    final RRect thumb = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(s * swW * 0.36, -swH * 0.02), width: swW * 0.135, height: swH * 0.195),
      const Radius.circular(10),
    );
    canvas.drawRRect(thumb, gloveShader);
    canvas.drawRRect(
      thumb,
      Paint()
        ..isAntiAlias = true
        ..color = const Color(0x55000000)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.6,
    );

    canvas.drawLine(
      Offset(s * swW * 0.41, swH * 0.04),
      Offset(s * swW * 0.49, swH * 0.24),
      Paint()..isAntiAlias = true..color = const Color(0x3DFFFFFF)..strokeWidth = 1.9,
    );
    canvas.drawLine(
      Offset(s * swW * 0.37, swH * 0.36),
      Offset(s * swW * 0.53, swH * 0.36),
      Paint()..isAntiAlias = true..color = livery.secondary.withAlpha(175)..strokeWidth = 2.6,
    );
  }

  void _drawChaseCarPro(Canvas canvas, double w, double h) {
    final TeamLivery livery = engine.livery;
    final bool ersOn = engine.ersActive;

    canvas.save();
    canvas.translate(w * 0.5, h * 0.80);
    canvas.rotate(engine.steerAngle * 0.065 + engine.spinYaw * 0.45);

    final Rect shad = Rect.fromCenter(center: const Offset(0, 14), width: 196, height: 32);
    canvas.drawOval(
      shad,
      Paint()
        ..shader = const RadialGradient(
          colors: [Color(0xDD000000), Color(0x00000000)],
        ).createShader(shad),
    );
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-84, -24, 30, 46), const Radius.circular(6)), Paint()..isAntiAlias = true..color = const Color(0xFF13161C));
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(54, -24, 30, 46), const Radius.circular(6)), Paint()..isAntiAlias = true..color = const Color(0xFF13161C));
    canvas.drawRect(const Rect.fromLTWH(-46, 2, 92, 14), Paint()..color = const Color(0xFF181C24));

    final Path body = Path()
      ..moveTo(-56, 4)
      ..lineTo(-35, -42)
      ..lineTo(35, -42)
      ..lineTo(56, 4)
      ..close();
    canvas.drawPath(
      body,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [livery.primaryLight, livery.primary, livery.primaryDark],
        ).createShader(const Rect.fromLTWH(-56, -42, 112, 46)),
    );

    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-12, -55, 24, 24), const Radius.circular(10)), Paint()..isAntiAlias = true..color = const Color(0xFF1A1D24));
    canvas.drawRect(const Rect.fromLTWH(-4, -2, 8, 10), Paint()..color = const Color(0xFFFF1744));
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(-62, ersOn ? -50 : -42, 124, ersOn ? 7 : 13), const Radius.circular(3)),
      Paint()..isAntiAlias = true..color = ersOn ? const Color(0xFF00E5FF) : livery.secondary,
    );
    canvas.restore();
  }

  void _drawCenteredText(Canvas canvas, String text, Offset center, double fontSize, Color color, FontWeight weight) {
    final TextPainter tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(color: color, fontSize: fontSize, fontWeight: weight),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(center.dx - tp.width * 0.5, center.dy - tp.height * 0.5));
  }

  @override
  bool shouldRepaint(covariant F1Pro120FpsPainter oldDelegate) => false;
}
